SELECT id, log_ts, latency_ms, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, context['version'] AS version, COALESCE(context['region'], 'unknown') AS region_or_default FROM app_logs WHERE TO_DATE(log_ts) >= '2024-08-01';
